@spec arrange_view_spec  src=tests/specs/arrange_view_spec.lua  loc=1109  cases=64
@exercises configManager (h.cm), arrangeManager (am), commandManager (h.cmgr), arrangeView (av)
@surface   cm:set, am:resizeTake, am:tracksTakes, cmgr:push, av:cursorRow, av:cursorCol, av:setCursor, av:setBeatPerRow, av:setCursorAt, av:setGridSize, av:scroll, av:scrollBy, av:setMaxCol, av:beatPerRow, cm:get, av:rowToQN, av:paletteSlot, av:setPaletteSlot, av:focus, av:setFocus, cmgr:invoke, av:tracksTakes, av:lassoCandidate, av:selectionSet, av:isSelected, av:selectBand, cmgr:pop, av:dropBand, av:setSelection, av:addToSelection, av:toggleSelected, av:dragCandidate, av:commitDrag, am:loopRangeQN, am:editCursorQN, am:trimHead, av:cursorTake, av:qnToRow
@harness   mk, reaper:setTrackName, reaper:addItem, reaper:setProjectTracks, reaper.GetSetRepeat

# Intent
  arrangeView: in-memory cursor/scroll + persisted beatPerRow, mirroring
  the trackerView/editCursor split (cursor is transient, density persists).

# Helpers
  @fn mkAv(harness)  @ 7-13
  @fn mkArrange(harness, items)  @ 17-36
      -- Build an av over a fake project. items: list of {track, name, pos, len?}.
      -- Tracks are created in first-seen order; beatPerRow is 1 (1 row = 1 QN).
  @fn takeAt(list, startQN)  @ 38-40
  @fn mkTrimmable(harness)  @ 44-51
      -- One four-row take at rows 2..5, with four rows of source left over: enough
      -- room for the head to walk in and for the tail to grow.

# Cases
  @case 'cursor defaults to (0,0); setCursor clamps negatives and floors'  [harness]  @ 72-80
  @case 'setCursorAt lands the caret on the row holding a project QN'  [harness]  @ 85-92
  @case 'scroll defaults to (0,0); setGridSize alone does not move scroll'  [harness]  @ 96-102
  @case 'cursor moving below the visible band scrolls down to follow'  [harness]  @ 106-113
  @case 'cursor moving above the visible band scrolls up to follow'  [harness]  @ 117-125
  @case 'horizontal follow tracks cursorCol against gridCols'  [harness]  @ 129-139
  @case 'setGridSize shrinking the viewport re-follows the cursor in place'  [harness]  @ 143-154
  @case 'scrollBy pans the viewport without moving the cursor'  [harness]  @ 158-167
  @case 'scrollBy clamps to >= 0 and cursor-nav re-follows the cursor'  [harness]  @ 171-182
  @case 'scroll-right stops once the last column is fully visible'  [harness]  @ 186-194
  @case 'a same-dims setGridSize after a wheel-scroll leaves scroll alone'  [harness]  @ 198-206
  @case 'beatPerRow defaults to cm value; setter clamps minimum'  [harness]  @ 210-219
  @case 'setBeatPerRow holds the cursor QN (zoom anchors on cursor) and clamps max'  [harness]  @ 223-235
  @case 'paletteSlot defaults nil; setter clamps to 0..61; nil clears'  [harness]  @ 239-253
  @case 'focus defaults nil; setFocus stores an opaque handle, nil clears'  [harness]  @ 257-266
  @case 'no selection + on-screen cursor: edit acts on the cursor take, leaves it unselected'  [harness]  @ 270-286
  @case 'no selection + off-screen cursor: an edit is a no-op'  [harness]  @ 290-306
  @case 'a held selection wins over the cursor take'  [harness]  @ 310-329
  @case 'lasso selects every take whose span intersects the swept rect'  [harness]  @ 333-349
  @case 'Shift+arrow selects every take the anchor-to-cursor rect covers'  [harness]  @ 353-366
  @case 'Shift+arrow sideways widens the rect into the next column'  [harness]  @ 370-381
  @case 'Shift+arrow back toward the anchor drops what it uncovers'  [harness]  @ 385-399
  @case 'a plain cursor move ends the run, so the next Shift+arrow re-anchors'  [harness]  @ 403-415
  @case 'a bare cursor move clears the selection'  [harness]  @ 419-429
  @case 'Home clears the selection like any other bare nav'  [harness]  @ 433-443
  @case 'Tab walks down the column, stopping at each start and each free row after a take'  [harness]  @ 447-465
  @case 'abutting takes collapse their shared boundary to one Tab stop'  [harness]  @ 469-480
  @case 'Shift+Tab walks back up, snapping to the start of the take it is inside'  [harness]  @ 484-498
  @case 'Tab only sees the takes in the cursor column'  [harness]  @ 502-515
  @case 'Tab clears the selection like any other bare nav'  [harness]  @ 519-530
  @case 'an edit's own cursor advance keeps the selection'  [harness]  @ 534-545
  @case 'the pooled duplicate clears the selection and lands the caret on the copy'  [harness]  @ 549-566
  @case 'the band stands through a run and comes down on the next command'  [harness]  @ 570-588
  @case 'a click takes the band down without waiting for a command'  [harness]  @ 592-603
  @case 'dropBand takes the band down and pops its scope'  [harness]  @ 607-617
  @case 'a multi-selection deletes every selected take in one pass'  [harness]  @ 621-635
  @case 'nudge refuses entirely when any selected take is blocked'  [harness]  @ 639-656
  @case 'nudge slides a contiguous selected block without self-collision'  [harness]  @ 660-675
  @case 'a single-target command no-ops on a multi-selection'  [harness]  @ 679-692
  @case 'arrangeClearSelection empties the selection'  [harness]  @ 696-707
  @case 'addToSelection unions handles without duplicating a present one'  [harness]  @ 711-725
  @case 'toggleSelected adds an absent handle and removes a present one'  [harness]  @ 729-742
  @case 'group drag slides the whole selection by one delta'  [harness]  @ 746-762
  @case 'group drag refuses when a member would hit an outside take'  [harness]  @ 766-779
  @case 'group drag with Alt duplicates the block and reselects the copies'  [harness]  @ 783-801
  @case 'loop to item brackets the take under the arrange cursor'  [harness]  @ 807-823
  @case 'loop to item takes the selection over the cursor, and spans a block'  [harness]  @ 827-844
  @case 'a cursor-driven replace leaves nothing selected'  [harness]  @ 848-860
  @case 'a replace of a selected take hands the selection to the replacement'  [harness]  @ 864-879
  @case 'a replace of a selection away from the cursor leaves the cursor alone'  [harness]  @ 883-895
  @case 'with advance-by-length armed, a drop advances by the take it placed'  [harness]  @ 901-914
  @case 'advance-by-length reads the clipped length, not the slot length'  [harness]  @ 918-931
  @case 'a second Ctrl-` puts the drop advance back on arrangeAdvanceBy'  [harness]  @ 935-949
  @case 'the caret on a start row moves the head down, holding the end still'  [harness]  @ 956-965
  @case 'the split key cuts the take at the caret and leaves the caret on the lower half'  [harness]  @ 969-979
  @case 'a split on the start row has nothing to cut'  [harness]  @ 983-989
  @case 'the caret off the start row moves the tail, leaving the head alone'  [harness]  @ 993-1002
  @case 'Up on the start row hands back a row of head, taking the caret with it'  [harness]  @ 1006-1016
  @case 'a head at the origin refuses to grow, and the caret holds'  [harness]  @ 1020-1029
  @case 'the take under the cursor carries the source its box hides'  [harness]  @ 1033-1044
  @case 'a head trim is floored at one rendered row'  [harness]  @ 1048-1058
  @case 'a tail shrink never parks the caret on the head row'  [harness]  @ 1062-1075
  @case 'the armed edge is decided once, from the take the caret stands on'  [harness]  @ 1079-1094
  @case 'qnToRow / rowToQN are inverses through beatPerRow'  [harness]  @ 1098-1107

